#!/usr/bin/env node
// Builds the RoboMeet Bridge extension's generated files:
//   config.js         local ports + shared secret (secret lives in data/bridge-secret, mode 600)
//   robot-main.js     src/meet-media.js + robot agent, active only in robot windows the extension opened
//   observer-main.js  verification observer, active only in observer windows the extension opened
// usage: node bin/bridge-build.mjs [--out DIR] [--ports 4321,4322] [--secret-file FILE]
import { createHash, randomBytes } from 'node:crypto';
import { cpSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const appRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const source = join(appRoot, 'extension');

export function buildBridge({ out = source, ports = [4321, 4322], secretFile = join(appRoot, 'data', 'bridge-secret') } = {}) {
  mkdirSync(dirname(secretFile), { recursive: true });
  if (!existsSync(secretFile)) writeFileSync(secretFile, randomBytes(24).toString('hex'), { mode: 0o600 });
  const secret = readFileSync(secretFile, 'utf8').trim();
  if (resolve(out) !== source) {
    mkdirSync(out, { recursive: true });
    for (const file of ['manifest.json', 'sw.js']) cpSync(join(source, file), join(out, file));
  }
  const part = name => readFileSync(join(source, 'parts', name), 'utf8');
  const meetMedia = readFileSync(join(appRoot, 'src', 'meet-media.js'), 'utf8');
  const wrap = (role, body) => `// GENERATED by bin/bridge-build.mjs. Do not edit; edit extension/parts/* or src/meet-media.js and rebuild.
(() => {
  let role = null;
  try {
    const match = location.hash.match(/robomeet-(robot|observer)=([a-f0-9]{8,64})/);
    if (match) sessionStorage.setItem('robomeet-role', match[1]);
    role = sessionStorage.getItem('robomeet-role');
  } catch {}
  if (role !== ${JSON.stringify(role)}) return;
  const robomeetQueue = { candidates: [], events: [] };
  window.__robomeetSignal = async item => { robomeetQueue.candidates.push(item); };
  window.__robomeetMediaEvent = data => {
    robomeetQueue.events.push(data);
    if (robomeetQueue.events.length > 300) robomeetQueue.events.splice(0, robomeetQueue.events.length - 300);
  };
${body}
})();
`;
  writeFileSync(join(out, 'config.js'), `self.ROBOMEET_BRIDGE = ${JSON.stringify({ ports, secret })};\n`, { mode: 0o600 });
  writeFileSync(join(out, 'robot-main.js'), wrap('robot', [meetMedia, part('agent-common.js'), part('robot-agent.js')].join('\n')));
  writeFileSync(join(out, 'observer-main.js'), wrap('observer', [part('agent-common.js'), part('observer-agent.js')].join('\n')));
  const stamp = createHash('sha256').update(meetMedia).digest('hex');
  writeFileSync(join(out, 'build.json'), JSON.stringify({ meetMediaSha256: stamp, ports }, null, 1));
  return { out, ports, stamp };
}

export function bridgeIsStale(out = source) {
  try {
    const { meetMediaSha256 } = JSON.parse(readFileSync(join(out, 'build.json'), 'utf8'));
    return meetMediaSha256 !== createHash('sha256').update(readFileSync(join(appRoot, 'src', 'meet-media.js'))).digest('hex');
  } catch { return true; }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const arg = name => { const index = process.argv.indexOf(name); return index > 0 ? process.argv[index + 1] : undefined; };
  const result = buildBridge({
    ...(arg('--out') ? { out: resolve(arg('--out')) } : {}),
    ...(arg('--ports') ? { ports: arg('--ports').split(',').map(Number) } : {}),
    ...(arg('--secret-file') ? { secretFile: resolve(arg('--secret-file')) } : {}),
  });
  console.log(`RoboMeet Bridge built in ${result.out} (ports ${result.ports.join(', ')}).`);
  if (result.out === source) {
    console.log('One-time setup in the Chrome window signed in as the robot account:');
    console.log('  1. Open chrome://extensions   2. Turn on "Developer mode"   3. Click "Load unpacked"');
    console.log(`  4. Choose ${source}`);
    console.log('If it is already loaded and you rebuilt, click its reload icon on chrome://extensions.');
  }
}
